export type FeatureGateProps = {
  flag: FeatureFlagKey;
  fallback?: ReactNode;
  children?: ReactNode;
};

/** The flag twin of `PermissionGate`: `readFlag` consults the snapshot the
20→ *  layout installed and falls back to `isEnabled()` for unknown keys. */
